"use client";
import { Icon, Card, Badge, Button, IconButton, Field, Toggle, Modal, Empty, SearchBar } from "@/components/ui";
export function Settings({dark,setDark,lang,setLang,user,t}:any){return <div className="responsiveGrid"><Card><h2>{t("appearance")}</h2><p className="muted">{t("appearanceSub")}</p><div className="two settingsChoices"><button className={`choice ${!dark?"selected":""}`} onClick={()=>setDark(false)}><Icon name="sun"/><span>{t("light")}</span></button><button className={`choice ${dark?"selected":""}`} onClick={()=>setDark(true)}><Icon name="moon"/><span>{t("dark")}</span></button></div></Card><Card><h2>{t("language")}</h2><div className="two settingsChoices"><button className={`choice ${lang==="fr"?"selected":""}`} onClick={()=>setLang("fr")}>FR · {t("french")}</button><button className={`choice ${lang==="en"?"selected":""}`} onClick={()=>setLang("en")}>EN · {t("english")}</button></div></Card><Card><h2>{t("emails")}</h2><p className="muted">{user.email}</p><p className="hint">Les emails automatiques utilisent l’expéditeur configuré dans le backend.</p></Card></div>}
