"use client";
import { Icon, Card, Badge, Button, IconButton, Empty, SearchBar } from "@/components/ui";
import { yearMonthGroups, monthOnlyLabel, yearLabel } from "@/lib/utils";
export function History({history,search,setSearch,deleteHistory,clearAll,t}:any){
 const q=search.trim().toLowerCase();
 const filtered=history.filter((h:any)=>!q||`${h.title||""} ${h.groupName||""} ${h.details||""} ${h.status||""}`.toLowerCase().includes(q));
 return <div className="stack historyPage"><div className="historyHeader"><div className="historyTitle"><p>{t("history")}</p><small className="muted">Les actions importantes de vos rappels et paiements sont conservées ici.</small></div>{!!history.length&&<Button kind="danger" onClick={clearAll}><Icon name="trash"/> {t("clearHistory")}</Button>}</div><div className="historySearch"><SearchBar value={search} setValue={setSearch} placeholder={t("searchHistory")}/></div>{filtered.length?yearMonthGroups(filtered,"occurredAt",true).map(([year,months])=><section className="yearSection" key={year}><h2 className="yearHeader">{yearLabel(year)}</h2>{months.map(([month,items]:any)=><div className="monthSection" key={month}><div className="monthHeader"><Icon name="history" size={17}/><h3>{monthOnlyLabel(month)}</h3></div><div className="historyList">{items.map((h:any)=><Card key={h.id} className="historyCard"><div className="historyItem"><span className="statIcon cyan historyIcon"><Icon name={h.activityType==="PAYMENT"?"money":"check"}/></span><div className="historyContent"><b className="historyMainText">{h.activityType==="PAYMENT"?t("historyPayment"):t("historyDone")} — {h.title||"Échéance"}</b><small className="historyMeta">{h.reminderType==="GROUP"?t("historyGroup"):t("historyPersonal")}{h.groupName?` · ${h.groupName}`:""}{h.occurredAt?` · ${new Date(h.occurredAt).toLocaleString("fr-FR")}`:""}</small><small className="historyDetails">{h.details||"—"}</small></div><div className="historyActions"><Badge tone={h.status==="PARTIAL"?"warning":h.status==="OVERPAID"?"info":"success"}>{h.status||"DONE"}</Badge><IconButton name="trash" onClick={()=>deleteHistory(h.id)} title={t("remove")}/></div></div></Card>)}</div></div>)}</section>):<Empty text={q?t("noResults"):t("noData")}/>}</div>
}
