"use client";
import { Icon, Card, Badge, Button, IconButton, Field, Toggle, Modal, Empty, SearchBar } from "@/components/ui";
import { money, dateFr, initials, recurrenceOptions, monthGroups, monthLabel } from "@/lib/utils";
import { Stat } from "@/components/dashboard/Stat";
export function Dashboard({stats,reminders,groups,setView,setModal,openGroup,t}:any){return <div className="stack"><div className="pageIntro"><div><p>{t("dashboardIntro")}</p></div><Button onClick={()=>setModal("reminder")}><Icon name="plus" size={17}/> {t("addReminder")}</Button></div><div className="statGrid"><Stat title={t("active")} value={stats.upcoming} icon="clock"/><Stat title={t("overdueCount")} value={stats.overdue} icon="history" tone="danger"/><Stat title={t("planned")} value={money(stats.expected)} icon="money" tone="cyan"/><Stat title={t("completed")} value={stats.paid} icon="check" tone="success"/></div><div className="twoCol"><Card><div className="cardHead"><div><h2>{t("next")}</h2><small>{t("reminders")}</small></div><button className="textLink" onClick={()=>setView("reminders")}>{t("all")}</button></div><div className="list">{reminders.filter((x:any)=>!x.paid&&!x.isPaid).sort((a:any,b:any)=>a.dueDate.localeCompare(b.dueDate)).slice(0,5).map((x:any)=><div className="listRow" key={x.id}><div className="dateBox"><b>{new Date(`${x.dueDate}T00:00:00`).getDate()}</b><small>{new Date(`${x.dueDate}T00:00:00`).toLocaleDateString("fr-FR",{month:"short"})}</small></div><div className="min0 grow"><b>{x.title}</b><small>{dateFr(x.dueDate)}</small></div></div>)}{!reminders.length&&<Empty text={t("firstReminder")}/>}</div></Card><Card><div className="cardHead"><div><h2>{t("groups")}</h2><small>{t("groupSpaces")}</small></div><button className="textLink" onClick={()=>setView("groups")}>{t("all")}</button></div><div className="list">{groups.slice(0,4).map((g:any)=><button className="listRow clickable" key={g.id} onClick={()=>openGroup(g)}><div className="avatar cyan">{initials(g.name)}</div><div className="min0 grow"><b>{g.name}</b><small>{g.description||"Échéo"}</small></div><Icon name="arrowRight"/></button>)}{!groups.length&&<Empty text={t("firstGroup")}/>}</div></Card></div></div>}
