"use client";
import { Icon, Card, Badge, Button, IconButton, Field, Toggle, Modal, Empty, SearchBar } from "@/components/ui";
import { money, dateFr, initials, recurrenceOptions, yearMonthGroups, monthOnlyLabel, yearLabel } from "@/lib/utils";
export function Reminders({reminders,search,setSearch,statusFilter,setStatusFilter,setModal,startEdit,deleteReminder,markDone,t,toggleRecurrence}:any){const q=search.trim().toLowerCase();const today=new Date().toISOString().slice(0,10);const filtered=reminders.filter((r:any)=>{const done=!!(r.paid||r.isPaid);const status=done?"DONE":r.dueDate<today?"OVERDUE":"UPCOMING";return (!q||`${r.title} ${r.description||""}`.toLowerCase().includes(q))&&(statusFilter==="ALL"||statusFilter===status)});return <div className="stack"><div className="pageIntro"><div><p>{t("reminders")}</p></div><Button onClick={setModal}><Icon name="plus"/> {t("addReminder")}</Button></div><div className="toolbar"><SearchBar value={search} setValue={setSearch} placeholder={t("searchReminders")}/><select className="input filterSelect" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option value="ALL">{t("allStatuses")}</option><option value="UPCOMING">{t("upcoming")}</option><option value="OVERDUE">{t("overdue")}</option><option value="DONE">{t("done")}</option></select></div>{yearMonthGroups(filtered).map(([year,months])=><div className="yearSection" key={year}><h2 className="yearHeader">{yearLabel(year)}</h2>{months.map(([month,items]:any)=><div className="monthSection" key={month}><div className="monthHeader"><Icon name="clock" size={17}/><h3>{monthOnlyLabel(month)}</h3></div><div className="responsiveGrid">{items.map((r:any)=><Card key={r.id}><div className="cardHead"><div><Badge tone={r.paid||r.isPaid?"success":r.dueDate<today?"danger":"info"}>{r.paid||r.isPaid?t("done"):r.dueDate<today?t("overdue"):t("upcoming")}</Badge><h3>{r.title}</h3></div><div className="rowBtns">{!(r.paid||r.isPaid)&&<IconButton name="edit" onClick={()=>startEdit(r)} title={t("edit")}/>}<IconButton name="trash" onClick={()=>deleteReminder(r.id)} title={t("remove")}/></div></div><p className="muted desc">{r.description||"—"}</p><div className="meta"><span>{dateFr(r.dueDate)}</span>{r.recurrence&&r.recurrence!=="NONE"&&<Badge tone={r.recurrenceActive===false?"warning":"neutral"}>{r.recurrenceActive===false?t("recurrenceStopped"):t(recurrenceOptions(r.recurrence) as any)}</Badge>}</div><div className="actions">{!(r.paid||r.isPaid)&&<Button kind="secondary" onClick={()=>markDone(r.id)}><Icon name="check"/> {t("markDone")}</Button>}{r.recurrence&&r.recurrence!=="NONE"&&<Button kind="secondary" onClick={()=>toggleRecurrence(r)}>{r.recurrenceActive===false?t("resumeRecurrence"):t("stopRecurrence")}</Button>}</div></Card>)}</div></div>)}</div>)}{!filtered.length&&<Empty text={q||statusFilter!=="ALL"?t("noResults"):t("firstReminder")}/>}</div>}
